import './styles.css';
import { useState, useCallback } from 'react';

interface Layer {
  id: string;
  neurons: number;
  type: 'input' | 'hidden' | 'output';
}

interface Connection {
  from: { layer: number; neuron: number };
  to: { layer: number; neuron: number };
  weight: number;
}

const initialLayers: Layer[] = [
  { id: 'input', neurons: 3, type: 'input' },
  { id: 'hidden1', neurons: 4, type: 'hidden' },
  { id: 'output', neurons: 2, type: 'output' },
];

function generateConnections(layers: Layer[]): Connection[] {
  const connections: Connection[] = [];
  for (let l = 0; l < layers.length - 1; l++) {
    for (let i = 0; i < layers[l].neurons; i++) {
      for (let j = 0; j < layers[l + 1].neurons; j++) {
        connections.push({
          from: { layer: l, neuron: i },
          to: { layer: l + 1, neuron: j },
          weight: Math.random() * 2 - 1,
        });
      }
    }
  }
  return connections;
}

function NetworkVisualization({ 
  layers, 
  connections, 
  activeNeurons,
  pulsePhase 
}: { 
  layers: Layer[]; 
  connections: Connection[];
  activeNeurons: Set<string>;
  pulsePhase: number;
}) {
  const width = 600;
  const height = 350;
  const layerWidth = width / (layers.length + 1);

  const getNeuronPos = (layerIdx: number, neuronIdx: number, totalNeurons: number) => {
    const x = (layerIdx + 1) * layerWidth;
    const neuronSpacing = Math.min(60, (height - 80) / totalNeurons);
    const startY = (height - (totalNeurons - 1) * neuronSpacing) / 2;
    const y = startY + neuronIdx * neuronSpacing;
    return { x, y };
  };

  return (
    <svg viewBox={`0 0 ${width} ${height}`} className="network-svg">
      <defs>
        <linearGradient id="pulseGradient" x1="0%" y1="0%" x2="100%" y2="0%">
          <stop offset="0%" stopColor="#8b5cf6" stopOpacity="0" />
          <stop offset={`${pulsePhase}%`} stopColor="#8b5cf6" stopOpacity="1" />
          <stop offset="100%" stopColor="#8b5cf6" stopOpacity="0" />
        </linearGradient>
      </defs>

      {/* Connections */}
      {connections.map((conn, idx) => {
        const fromPos = getNeuronPos(conn.from.layer, conn.from.neuron, layers[conn.from.layer].neurons);
        const toPos = getNeuronPos(conn.to.layer, conn.to.neuron, layers[conn.to.layer].neurons);
        const isActive = activeNeurons.has(`${conn.from.layer}-${conn.from.neuron}`);

        return (
          <line
            key={idx}
            x1={fromPos.x}
            y1={fromPos.y}
            x2={toPos.x}
            y2={toPos.y}
            stroke={isActive ? '#8b5cf6' : '#e5e7eb'}
            strokeWidth={isActive ? 2 : 1}
            opacity={Math.abs(conn.weight) * 0.5 + 0.2}
            className={isActive ? 'connection-active' : ''}
          />
        );
      })}

      {/* Layer labels */}
      {layers.map((layer, layerIdx) => {
        const x = (layerIdx + 1) * layerWidth;
        return (
          <text
            key={`label-${layer.id}`}
            x={x}
            y={25}
            textAnchor="middle"
            className="layer-label"
          >
            {layer.type === 'input' ? 'Input' : layer.type === 'output' ? 'Output' : `Hidden ${layerIdx}`}
          </text>
        );
      })}

      {/* Neurons */}
      {layers.map((layer, layerIdx) => (
        Array.from({ length: layer.neurons }).map((_, neuronIdx) => {
          const pos = getNeuronPos(layerIdx, neuronIdx, layer.neurons);
          const isActive = activeNeurons.has(`${layerIdx}-${neuronIdx}`);

          return (
            <g key={`${layerIdx}-${neuronIdx}`}>
              <circle
                cx={pos.x}
                cy={pos.y}
                r={18}
                className={`neuron ${layer.type} ${isActive ? 'active' : ''}`}
              />
              <text
                x={pos.x}
                y={pos.y + 5}
                textAnchor="middle"
                className="neuron-label"
              >
                {layerIdx === 0 ? `x${neuronIdx + 1}` : layerIdx === layers.length - 1 ? `y${neuronIdx + 1}` : ''}
              </text>
            </g>
          );
        })
      ))}
    </svg>
  );
}

export default function App() {
  const [layers, setLayers] = useState<Layer[]>(initialLayers);
  const [connections, setConnections] = useState<Connection[]>(() => generateConnections(initialLayers));
  const [isAnimating, setIsAnimating] = useState(false);
  const [activeNeurons, setActiveNeurons] = useState<Set<string>>(new Set());
  const [pulsePhase, setPulsePhase] = useState(0);

  const addHiddenLayer = () => {
    const newLayers = [...layers];
    const insertIdx = newLayers.length - 1;
    newLayers.splice(insertIdx, 0, {
      id: `hidden${Date.now()}`,
      neurons: 3,
      type: 'hidden',
    });
    setLayers(newLayers);
    setConnections(generateConnections(newLayers));
  };

  const removeHiddenLayer = () => {
    if (layers.filter(l => l.type === 'hidden').length > 0) {
      const newLayers = layers.filter((l, i) => !(l.type === 'hidden' && i === layers.length - 2));
      setLayers(newLayers);
      setConnections(generateConnections(newLayers));
    }
  };

  const adjustNeurons = (layerIdx: number, delta: number) => {
    const newLayers = [...layers];
    const newCount = Math.max(1, Math.min(8, newLayers[layerIdx].neurons + delta));
    newLayers[layerIdx] = { ...newLayers[layerIdx], neurons: newCount };
    setLayers(newLayers);
    setConnections(generateConnections(newLayers));
  };

  const runForwardPass = useCallback(() => {
    if (isAnimating) return;
    setIsAnimating(true);

    let currentLayer = 0;
    const animate = () => {
      if (currentLayer < layers.length) {
        const newActive = new Set<string>();
        for (let n = 0; n < layers[currentLayer].neurons; n++) {
          newActive.add(`${currentLayer}-${n}`);
        }
        setActiveNeurons(newActive);
        currentLayer++;
        setTimeout(animate, 500);
      } else {
        setActiveNeurons(new Set());
        setIsAnimating(false);
      }
    };
    animate();
  }, [isAnimating, layers]);

  const hiddenCount = layers.filter(l => l.type === 'hidden').length;
  const totalConnections = connections.length;
  const totalParams = totalConnections + layers.slice(1).reduce((sum, l) => sum + l.neurons, 0);

  return (
    <div className="app">
      <div className="header">
        <h1>Neural Network Builder</h1>
        <p className="subtitle">
          Build your own network! Add layers, adjust neurons, and watch data flow through.
        </p>
      </div>

      <div className="visualization-container">
        <NetworkVisualization 
          layers={layers} 
          connections={connections}
          activeNeurons={activeNeurons}
          pulsePhase={pulsePhase}
        />
      </div>

      <div className="controls-panel">
        <div className="control-group">
          <h3>Layers</h3>
          <div className="button-row">
            <button onClick={addHiddenLayer} className="btn primary">
              + Add Hidden Layer
            </button>
            <button 
              onClick={removeHiddenLayer} 
              className="btn secondary"
              disabled={hiddenCount === 0}
            >
              - Remove Layer
            </button>
          </div>
        </div>

        <div className="control-group">
          <h3>Neurons per Layer</h3>
          <div className="layer-controls">
            {layers.map((layer, idx) => (
              <div key={layer.id} className="layer-control">
                <span className="layer-name">
                  {layer.type === 'input' ? 'Input' : layer.type === 'output' ? 'Output' : `Hidden ${idx}`}
                </span>
                <div className="neuron-adjuster">
                  <button onClick={() => adjustNeurons(idx, -1)}>-</button>
                  <span className="neuron-count">{layer.neurons}</span>
                  <button onClick={() => adjustNeurons(idx, 1)}>+</button>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="control-group">
          <h3>Simulate</h3>
          <button 
            onClick={runForwardPass} 
            className="btn run"
            disabled={isAnimating}
          >
            {isAnimating ? 'Running...' : 'Run Forward Pass'}
          </button>
        </div>
      </div>

      <div className="stats-panel">
        <div className="stat">
          <span className="stat-value">{layers.length}</span>
          <span className="stat-label">Total Layers</span>
        </div>
        <div className="stat">
          <span className="stat-value">{hiddenCount}</span>
          <span className="stat-label">Hidden Layers</span>
        </div>
        <div className="stat">
          <span className="stat-value">{totalConnections}</span>
          <span className="stat-label">Connections</span>
        </div>
        <div className="stat">
          <span className="stat-value">{totalParams}</span>
          <span className="stat-label">Parameters</span>
        </div>
      </div>

      <div className="insight-box">
        <h3>What You're Seeing</h3>
        <p>
          Each <strong>circle</strong> is a neuron. Each <strong>line</strong> is a connection with a weight.
          More hidden layers = deeper network = can learn more complex patterns.
        </p>
        <p>
          <strong>Try it:</strong> Add layers and watch the connection count explode. That's why deep networks need lots of data and compute!
        </p>
      </div>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: linear-gradient(135deg, #7c3aed 0%, #4f46e5 100%);
  min-height: 100vh;
  padding: 1.5rem 1rem;
}

.app {
  max-width: 800px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 1.5rem;
}

h1 {
  color: white;
  font-size: 1.75rem;
  margin-bottom: 0.5rem;
}

.subtitle {
  color: rgba(255, 255, 255, 0.85);
  font-size: 0.95rem;
}

.visualization-container {
  background: white;
  border-radius: 1rem;
  padding: 1rem;
  margin-bottom: 1rem;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.network-svg {
  width: 100%;
  height: auto;
}

.layer-label {
  font-size: 12px;
  fill: #6b7280;
  font-weight: 500;
}

.neuron {
  stroke-width: 2;
  transition: all 0.3s ease;
}

.neuron.input {
  fill: #dbeafe;
  stroke: #3b82f6;
}

.neuron.hidden {
  fill: #f3e8ff;
  stroke: #8b5cf6;
}

.neuron.output {
  fill: #dcfce7;
  stroke: #22c55e;
}

.neuron.active {
  fill: #8b5cf6;
  stroke: #6d28d9;
  filter: drop-shadow(0 0 8px rgba(139, 92, 246, 0.6));
}

.neuron-label {
  font-size: 10px;
  fill: #374151;
  font-weight: 600;
}

.connection-active {
  animation: pulse 0.5s ease-out;
}

@keyframes pulse {
  0% { stroke-width: 2; }
  50% { stroke-width: 4; }
  100% { stroke-width: 2; }
}

.controls-panel {
  background: white;
  border-radius: 1rem;
  padding: 1.25rem;
  margin-bottom: 1rem;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1.25rem;
}

.control-group h3 {
  font-size: 0.85rem;
  color: #374151;
  margin-bottom: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.button-row {
  display: flex;
  gap: 0.5rem;
}

.btn {
  padding: 0.5rem 1rem;
  border: none;
  border-radius: 0.5rem;
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}

.btn.primary {
  background: #8b5cf6;
  color: white;
}

.btn.primary:hover {
  background: #7c3aed;
}

.btn.secondary {
  background: #f3f4f6;
  color: #374151;
}

.btn.secondary:hover:not(:disabled) {
  background: #e5e7eb;
}

.btn.secondary:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.btn.run {
  background: #22c55e;
  color: white;
  width: 100%;
  padding: 0.75rem;
}

.btn.run:hover:not(:disabled) {
  background: #16a34a;
}

.btn.run:disabled {
  background: #86efac;
  cursor: not-allowed;
}

.layer-controls {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.layer-control {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.5rem;
  background: #f9fafb;
  border-radius: 0.5rem;
}

.layer-name {
  font-size: 0.8rem;
  color: #6b7280;
}

.neuron-adjuster {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.neuron-adjuster button {
  width: 28px;
  height: 28px;
  border: 1px solid #d1d5db;
  background: white;
  border-radius: 0.25rem;
  cursor: pointer;
  font-size: 1rem;
  color: #374151;
}

.neuron-adjuster button:hover {
  background: #f3f4f6;
}

.neuron-count {
  font-weight: 600;
  min-width: 20px;
  text-align: center;
}

.stats-panel {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.stat {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 0.75rem;
  padding: 1rem;
  text-align: center;
}

.stat-value {
  display: block;
  font-size: 1.5rem;
  font-weight: 700;
  color: white;
}

.stat-label {
  font-size: 0.75rem;
  color: rgba(255, 255, 255, 0.8);
}

.insight-box {
  background: rgba(255, 255, 255, 0.95);
  border-radius: 1rem;
  padding: 1.25rem;
}

.insight-box h3 {
  color: #1f2937;
  font-size: 1rem;
  margin-bottom: 0.75rem;
}

.insight-box p {
  color: #4b5563;
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 0.5rem;
}

.insight-box p:last-child {
  margin-bottom: 0;
}

@media (max-width: 600px) {
  .stats-panel {
    grid-template-columns: repeat(2, 1fr);
  }

  .controls-panel {
    grid-template-columns: 1fr;
  }
}
